# Dekopon publishes one archive per platform carrying all four executables, so
# one formula installs the whole system. Four formulae would each download the
# same tarball.
#
# Generated by .github/scripts/render-homebrew-formula.py in
# https://github.com/dekopon-agents/dekopon, from the archives release v0.3.0 published.
# Which platforms Dekopon supports is a property of each release, not of this
# tap. Edit the generator, not this file.
class Dekopon < Formula
  desc "Capability-oriented control plane for self-hosted AI agents"
  homepage "https://github.com/dekopon-agents/dekopon"
  license any_of: ["Apache-2.0", "MIT"]
  # No explicit `version`: Homebrew scans 0.3.0 out of the download URL, and
  # `brew audit --strict` rejects restating it.

  on_macos do
    on_arm do
      url "https://github.com/dekopon-agents/dekopon/releases/download/v0.3.0/dekopon-0.3.0-aarch64-apple-darwin.tar.gz"
      sha256 "03e272c769ddcaa7bfe7431dcf3b10c7e4d8b2fd717e9bc240c7d8564b462a69"
    end

    on_intel do
      url "https://github.com/dekopon-agents/dekopon/releases/download/v0.3.0/dekopon-0.3.0-x86_64-apple-darwin.tar.gz"
      sha256 "98f54a096f257e5533679f82682e0c8010835f5e2ffc239e11d73635e3904ada"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/dekopon-agents/dekopon/releases/download/v0.3.0/dekopon-0.3.0-aarch64-unknown-linux-gnu.tar.gz"
      sha256 "23860e3d1dd8f93c329516eec33117b4f4c5b8e29cefffbbdc6b8012d2371ab9"
    end

    on_intel do
      url "https://github.com/dekopon-agents/dekopon/releases/download/v0.3.0/dekopon-0.3.0-x86_64-unknown-linux-gnu.tar.gz"
      sha256 "f34112c5c02dc2ae8d87edaf020823ae2f33530811ab7fb40a16f593b9d87dee"
    end
  end

  def install
    bin.install "dekopon", "dekopon-run", "dekopon-brokerd", "dekopond"
    pkgshare.install "providers"
    doc.install "README.md", "BROKER.md", "GATEWAY.md", "LICENSE-APACHE", "LICENSE-MIT"
  end

  def caveats
    <<~EOS
      Dekopon installed four executables:

        dekopon          local agent catalog and model-account CLI
        dekopon-run      one-shot runner: components, sandboxed shell, prompt loop
        dekopon-brokerd  the authorization broker daemon (Unix only)
        dekopond         the unprivileged chat gateway daemon (Unix only)

      dekopon and dekopon-run need no setup:

        dekopon --config ./dekopon.yaml validate
        dekopon-run inspect --provider ./some-provider.wasm

      dekopon-brokerd and dekopond are daemons. Nothing was started, and neither
      runs until you write it an owner-authored configuration file:

        dekopon-brokerd --config broker.yaml    #{doc}/BROKER.md
        dekopond --config gateway.yaml          #{doc}/GATEWAY.md

      The broker holds provider credentials and the only authorization path;
      read BROKER.md before enabling it.

      The example JSONPlaceholder provider component is at

        #{pkgshare}/providers/jsonplaceholder-provider.wasm

      It imports broker-owned HTTP, which makes it a broker provider: name that
      path in broker.yaml. `dekopon-run inspect` is deliberately import-free and
      refuses to instantiate it. The constraint set and Cedar policy it needs are
      in #{pkgshare}/providers/JSONPLACEHOLDER.md.

      The end-to-end walkthrough is examples/rubber-stamper in the source tree:
      https://github.com/dekopon-agents/dekopon/tree/v0.3.0/examples/rubber-stamper
    EOS
  end

  test do
    assert_match "dekopon #{version}", shell_output("#{bin}/dekopon --version")
    assert_match "dekopon-run #{version}", shell_output("#{bin}/dekopon-run --version")
    assert_match "dekopon-brokerd #{version}", shell_output("#{bin}/dekopon-brokerd --version")
    assert_match "dekopond #{version}", shell_output("#{bin}/dekopond --version")

    component = pkgshare/"providers/jsonplaceholder-provider.wasm"
    assert_path_exists component
    assert_equal "\x00asm", component.binread(4), "example provider is not a Wasm component"

    # Exercise the catalog reader on a real cross-referenced catalog rather than
    # only proving the binaries start.
    (testpath/"dekopon.yaml").write <<~YAML
      apiVersion: dekopon.dev/v1alpha1
      kind: Provider
      metadata:
        name: jsonplaceholder
      spec:
        description: Example provider declaration
        type: http
        credentialRef: jsonplaceholder-default
      status: Unknown
      ---
      apiVersion: dekopon.dev/v1alpha1
      kind: Capability
      metadata:
        name: jsonplaceholder.posts.get
      spec:
        description: Read one JSONPlaceholder post
        provider: jsonplaceholder
        effect: read-only
        risk: Low
        idempotency: idempotent
        permissions:
          - operation: posts:read
      status: Unknown
      ---
      apiVersion: dekopon.dev/v1alpha1
      kind: Agent
      metadata:
        name: reader
      spec:
        description: Reads example posts and nothing else
        enabled: true
        capabilities:
          - jsonplaceholder.posts.get
        providers:
          - jsonplaceholder
        modelClass: analysis
        policyProfile: read-only
      status: Ready
    YAML

    assert_match "configuration valid",
                 shell_output("#{bin}/dekopon --config #{testpath}/dekopon.yaml validate")
    assert_equal "agent/reader",
                 shell_output("#{bin}/dekopon --config #{testpath}/dekopon.yaml get agents -o name").strip
  end
end
